import React from "react";
import styles from "../../app/page.module.css";
import PDFDownloadButton from "../../app/components/PDFDownloadButton";

// On importe uniquement le composant qui génère le PDF, pas ReportsList
import {
  Document,
  Page,
  Text,
  View,
  Image,
  StyleSheet,
  Font,
} from "@react-pdf/renderer";

// Enregistrement de la police personnalisée
Font.register({
  family: "BR Sonoma",
  src: "/font/BRSonomaSemibold.ttf",
  fontStyle: "normal",
  fontWeight: "normal",
});

// Styles PDF
const pdfStyles = StyleSheet.create({
  page: {
    backgroundColor: "#DBDFE0",
    padding: 32,
    fontFamily: "BR Sonoma",
  },
  logo: {
    width: 180,
    height: 80,
    marginBottom: 24,
    alignSelf: "center",
  },
  title: {
    fontSize: 28,
    color: "#1a7f6b",
    marginBottom: 12,
    textAlign: "center",
    fontFamily: "BR Sonoma",
    fontWeight: "bold",
  },
  section: {
    marginBottom: 18,
    padding: 12,
    backgroundColor: "#fff",
    borderRadius: 18,
    fontFamily: "BR Sonoma",
  },
  subtitle: {
    fontSize: 18,
    color: "#444444",
    marginBottom: 8,
    fontFamily: "BR Sonoma",
  },
  text: {
    fontSize: 14,
    color: "#222",
    marginBottom: 6,
    fontFamily: "BR Sonoma",
  },
  chartImage: {
    width: "100%",
    height: 180,
    borderRadius: 12,
    marginBottom: 12,
  },
});

// Générateur du PDF minimal pour l'historique
function ReportHistoryPDF({
  reportType,
  period,
  data,
  influenceHistory = [],
  chartImage = "",
  influenceChartImage = "",
  topUsersChartImage = "",
  companyName = "Vyft",
}: {
  reportType: string;
  period: string;
  data: any;
  influenceHistory?: any[];
  chartImage?: string;
  influenceChartImage?: string;
  topUsersChartImage?: string;
  companyName?: string;
}) {
  return (
    <Document>
      <Page size="A4" style={pdfStyles.page}>
        <Image src="/Vyft_program.png" style={pdfStyles.logo} />
        <Text style={pdfStyles.title}>
          Rapport {reportType === "weekly"
            ? "hebdomadaire"
            : reportType === "monthly"
            ? "mensuel"
            : "fiscal"}
        </Text>
        <Text
          style={{
            fontSize: 18,
            color: "#1a7f6b",
            textAlign: "center",
            marginBottom: 8,
            fontFamily: "BR Sonoma",
            fontWeight: "bold",
          }}
        >
          {companyName}
        </Text>
        <Text
          style={{
            ...pdfStyles.text,
            textAlign: "center",
            marginBottom: 12,
          }}
        >
          Période : {period}
        </Text>
        {/* Tu peux ajouter ici d'autres infos si besoin */}
      </Page>
    </Document>
  );
}

export default function ReportsHistory({ reports }: {
  reports: {
    type: string;
    label: string;
    period: string;
    data: any;
    influenceHistory: any;
    chartImage: string;
    influenceChartImage: string;
    topUsersChartImage: string;
    companyName?: string;
  }[];
}) {
  return (
    <section
      className={styles.bodyonwhite}
      style={{
        background: "#fff",
        borderRadius: 24,
        padding: 32,
        width: "100%",
        maxWidth: 420,
        boxShadow: "0 2px 8px rgba(0,0,0,0.07)",
        fontFamily: "BR Sonoma, BRSonoma, sans-serif",
      }}
    >
      <h2 className={styles.headeronwhite} style={{ fontSize: 22, marginBottom: 18 }}>
        Historique
      </h2>
      <ul style={{ listStyle: "none", padding: 0, margin: 0 }}>
        {reports.map((report, idx) => (
          <li
            key={idx}
            className={styles.bodyonwhite}
            style={{
              display: "flex",
              alignItems: "center",
              justifyContent: "space-between",
              background: "#DBDFE0",
              borderRadius: 18,
              padding: "18px 20px",
              marginBottom: 14,
              fontSize: 16,
              fontFamily: "BR Sonoma, BRSonoma, sans-serif",
            }}
          >
            <div>
              <div className={styles.headeronwhite} style={{ fontWeight: "bold", fontFamily: "BR Sonoma, BRSonoma, sans-serif" }}>
                Rapport {report.label}
              </div>
              <div className={styles.bodyonwhite} style={{ fontSize: 13, color: "#444", fontFamily: "BR Sonoma, BRSonoma, sans-serif" }}>
                {report.period}
              </div>
            </div>
            <PDFDownloadButton
              document={
                <ReportHistoryPDF
                  reportType={report.type}
                  period={report.period}
                  data={report.data}
                  influenceHistory={report.influenceHistory}
                  chartImage={report.chartImage}
                  influenceChartImage={report.influenceChartImage}
                  topUsersChartImage={report.topUsersChartImage}
                  companyName={report.companyName}
                />
              }
              fileName={`vyft-program-report-${report.type}-${report.period}.pdf`}
              style={{
                background: "#1a7f6b",
                border: "none",
                cursor: "pointer",
                padding: 0,
                marginLeft: 12,
                borderRadius: 8,
                width: 44,
                height: 44,
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                boxShadow: "0 2px 8px rgba(0,0,0,0.07)",
                fontFamily: "BR Sonoma, BRSonoma, sans-serif",
              }}
            >
              <img src="/nav_down.png" alt="Télécharger PDF" style={{ width: 28, height: 28, fontFamily: "BR Sonoma, BRSonoma, sans-serif" }} />
            </PDFDownloadButton>
          </li>
        ))}
      </ul>
    </section>
  );
}